#include <vector>
#include <stack>

class Solution {
public:
    long long subArrayRanges(std::vector<int>& nums) {
        int n = nums.size();

        auto sumExtrema = [&](bool isMax) -> long long {
            long long total = 0;
            std::stack<int> st;
            for (int i = 0; i <= n; ++i) {
                while (!st.empty() && (i == n || (isMax ? nums[st.top()] < nums[i] : nums[st.top()] > nums[i]))) {
                    int mid = st.top();
                    st.pop();
                    int left = st.empty() ? -1 : st.top();
                    int right = i;
                    long long count = 1LL * (mid - left) * (right - mid);
                    total += 1LL * nums[mid] * count;
                }
                st.push(i);
            }
            return total;
        };

        return sumExtrema(true) - sumExtrema(false);
    }
};

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public long subArrayRanges(int[] nums) {
        int n = nums.length;
        return sumExtrema(nums, n, true) - sumExtrema(nums, n, false);
    }

    private long sumExtrema(int[] nums, int n, boolean isMax) {
        long total = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i <= n; i++) {
            while (!stack.isEmpty() && (i == n || (isMax ? nums[stack.peek()] < nums[i] : nums[stack.peek()] > nums[i]))) {
                int mid = stack.pop();
                int left = stack.isEmpty() ? -1 : stack.peek();
                int right = i;
                long count = (long) (mid - left) * (right - mid);
                total += (long) nums[mid] * count;
            }
            stack.push(i);
        }
        return total;
    }
}

