var subArrayRanges = function(nums) {
    const n = nums.length;

    const sumExtrema = (isMax) => {
        let total = 0;
        const stack = [];
        for (let i = 0; i <= n; i++) {
            while (stack.length > 0 && (i === n || (isMax ? nums[stack[stack.length - 1]] < nums[i] : nums[stack[stack.length - 1]] > nums[i]))) {
                const mid = stack.pop();
                const left = stack.length > 0 ? stack[stack.length - 1] : -1;
                const right = i;
                const count = (mid - left) * (right - mid);
                total += nums[mid] * count;
            }
            stack.push(i);
        }
        return total;
    };

    return sumExtrema(true) - sumExtrema(false);
};
